UPDATE problem SET driver_code = '{"python": "import sys, json\nfrom typing import *\nimport collections\nimport math\nimport itertools\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n{USER_CODE}\ndef build(lst):\n    d = c = ListNode(0)\n    for v in lst: c.next = ListNode(int(v)); c = c.next\n    return d.next\nif __name__ == ''__main__'':\n    lines = sys.stdin.read().splitlines()\n    k = int(lines[0]) if lines and lines[0].strip() else 0\n    lists = []\n    for i in range(1, k + 1):\n        if i < len(lines):\n            line = lines[i]\n            if line.strip():\n                lists.append(build(line.split()))\n            else:\n                lists.append(None)\n    res = Solution().mergeKLists(lists)\n    out = []\n    while res: out.append(res.val); res = res.next\n    print(\"[\" + \",\".join(map(str, out)) + \"]\")"}' WHERE slug = 'merge-k-sorted-lists';
UPDATE problem SET driver_code = '{"python": "import sys, json\nfrom typing import *\nimport collections\nimport math\nimport itertools\n{USER_CODE}\nif __name__ == ''__main__'':\n    lines = sys.stdin.read().splitlines()\n    intervals = []\n    for line in lines:\n        if line.strip():\n            parts = line.split()\n            intervals.append([int(parts[0]), int(parts[1])])\n    res = Solution().merge(intervals)\n    print(json.dumps(res).replace(\" \", \"\"))"}' WHERE slug = 'merge-intervals';
